export const empty = '[data-command-item=""]';
export const valued = "[data-command-item='x']";
export const word = '[data-command-item~="x"]';
export const prefix = '[data-command-group|="a"] [data-command-input^=b]';
export const spaced = '[ data-command-item = "x" i ]';
export const escaped = "[data-command-item=\"x\"]";
